<?php

declare(strict_types=1); namespace App\Entity\Configurator; use App\Enum\Configurator\{DependencyEffect,DependencyOperator}; use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity] #[ORM\Table(name:'cardnext_configurator_dependency')] #[ORM\Index(name:'IDX_CN_CFG_DEP_LOOKUP',columns:['configurator_id','enabled','priority'])]
class ConfiguratorDependency { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne(targetEntity:Configurator::class),ORM\JoinColumn(nullable:false,onDelete:'CASCADE')] private Configurator $configurator; #[ORM\ManyToOne(targetEntity:ConfiguratorField::class),ORM\JoinColumn(nullable:false,onDelete:'CASCADE')] private ConfiguratorField $sourceField; #[ORM\Column(enumType:DependencyOperator::class,length:40)] private DependencyOperator $operator; #[ORM\Column(type:'json')] private array $expectedValues=[]; #[ORM\ManyToOne(targetEntity:ConfiguratorField::class),ORM\JoinColumn(nullable:true,onDelete:'CASCADE')] private ?ConfiguratorField $targetField=null; #[ORM\ManyToOne(targetEntity:ConfiguratorValue::class),ORM\JoinColumn(nullable:true,onDelete:'CASCADE')] private ?ConfiguratorValue $targetValue=null; #[ORM\Column(enumType:DependencyEffect::class,length:20)] private DependencyEffect $effect; #[ORM\Column] private int $priority=0; #[ORM\Column(options:['default'=>true])] private bool $enabled=true;
 /** @param list<string|int|bool> $expected */ public function __construct(Configurator $c,ConfiguratorField $source,DependencyOperator $op,array $expected,DependencyEffect $effect){$this->configurator=$c;$this->sourceField=$source;$this->operator=$op;$this->expectedValues=$expected;$this->effect=$effect;} public function getSourceField():ConfiguratorField{return $this->sourceField;} public function getOperator():DependencyOperator{return $this->operator;} public function getExpectedValues():array{return $this->expectedValues;} public function getTargetField():?ConfiguratorField{return $this->targetField;} public function setTargetField(?ConfiguratorField $v):void{$this->targetField=$v;} public function getTargetValue():?ConfiguratorValue{return $this->targetValue;} public function setTargetValue(?ConfiguratorValue $v):void{$this->targetValue=$v;} public function getEffect():DependencyEffect{return $this->effect;} public function isEnabled():bool{return $this->enabled;} public function setEnabled(bool $v):void{$this->enabled=$v;}
}
